--region import
---@type ChatConstants
local ChatConstants = import('Game.OverseaChat.ChatConstants')
local RegionQuestMgr = import('Game.UI.FightReady.UIMainChapter.RegionQuestMgr')
local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
--endregion import

--region define
local CoWait = CS.Engine.Lib.CoWait
local UIModule = CS.Engine.UI.UIModule
local PrefabCellName = "Cell"
--endregion define

--- from: Assets/BundleResources/Prefabs/OverseaChat/OverseaChatDialog.prefab
---@class OverseaChatRecruitPanel
---@field Env                           	OverseaChatRecruitPanel                 
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field CommonFilterNode2             	UnityEngine.RectTransform               
---@field CommonFilterNode1             	UnityEngine.RectTransform               
---@field Filter                        	UnityEngine.RectTransform               
---@field ScrollView                    	UnityEngine.RectTransform               
local OverseaChatRecruitPanel = Class("OverseaChatRecruitPanel")

--region lifecycle
function OverseaChatRecruitPanel:__init()
    self._receiveRecruitMsgEvent = nil -- 接收招募信息事件
    self._deleteRecruitMsgEvent  = nil -- 删除招募信息事件
    self._recruitData            = {}  -- 招募数据
    self._combatType             = 0   -- 歼灭战类型
    self._difficultyType         = 0   -- 难度类型
end

function OverseaChatRecruitPanel:__delete()
    self._receiveRecruitMsgEvent = nil
    self._deleteRecruitMsgEvent  = nil
    self._recruitData            = nil
    self._combatType             = nil
    self._difficultyType         = nil
end

function OverseaChatRecruitPanel:Awake()
    self:InitHandler()
    self:InitFilter()
end

function OverseaChatRecruitPanel:OnEnable()
    self:RefreshListView()
end

function OverseaChatRecruitPanel:OnDisable()
    ---防止占内存，清理一次
    self:ClearListView()
end

function OverseaChatRecruitPanel:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function OverseaChatRecruitPanel:InitHandler()
    self._receiveRecruitMsgEvent = Events.AddListener(ChatConstants.EventNames.NEW_RECRUIT_MESSAGE, Bind(self, self.ReceiveRecruitMsgEventHandler))
end

function OverseaChatRecruitPanel:InitFilter()
    local filterLScr = CfUtils.GetLuaScr(self.CommonFilterNode1, "Game.Behaviours.UICommonFilterMB")
    local filterRScr = CfUtils.GetLuaScr(self.CommonFilterNode2, "Game.Behaviours.UICommonFilterMB")
    filterLScr:SetPageType(Constants.UIFilterPageType.PullUP)
    local typeDataL = {{combatType = 0, typeDesc = localize("全部")}}
    local combatTypeConf = ActionUtils.GetAllRegionAnnihilationTypeVo()
    for _, v in ipairs(combatTypeConf) do
        table.insert(typeDataL, {
            combatType = checkInt(v.id), typeDesc = v.name
        })
    end
    filterLScr:InitSortTypeData(typeDataL)
    filterLScr:SetCallback({}, function()
        local selectIndex  = filterLScr.selectIndex
        local sortTypeData = filterLScr.sortTypeList[selectIndex]
        if self:GetCombatType() ~= sortTypeData.combatType then
            self:SetCombatType(sortTypeData.combatType)
            self:RefreshUI()
        end
    end)
    filterLScr:SetStyleType(2)
    filterLScr:RefreshUI()
    
    filterRScr:SetPageType(Constants.UIFilterPageType.PullUP)
    local typeDataR = {{difficultyType = 0, typeDesc = localize("全部难度")}}
    for i = 1, self:GetDifficultyNum() do
        table.insert(typeDataR, {
            difficultyType = i, typeDesc = localize("难度_num_", {_num_ = i})
        })
    end
    filterRScr:InitSortTypeData(typeDataR)
    filterRScr:SetCallback({}, function()
        local selectIndex  = filterRScr.selectIndex
        local sortTypeData = filterRScr.sortTypeList[selectIndex]
        if self:GetDifficultyType() ~= sortTypeData.difficultyType then
            self:SetDifficultyType(sortTypeData.difficultyType)
            self:RefreshUI()
        end
    end)
    filterRScr:SetStyleType(2)
    filterRScr:RefreshUI()
end
--endregion init

--region handler
---接收招募信息事件处理
function OverseaChatRecruitPanel:ReceiveRecruitMsgEventHandler()
    self:RefreshUI()
end

---cell加入按钮点击回调
function OverseaChatRecruitPanel:CellJoinBtnOnClickHandler(index)
    local data = self:GetRecruitData()[index]
    local activityUuid = isNull(data.activity) and 0 or checkNumber(data.activity.id)
    RegionQuestMgr:GetInstance():ChatEnterReq(data.mainId, activityUuid)
end

---列表刷新
function OverseaChatRecruitPanel:OnGetItemByIndex(gridView, index)
    if index < 0 then return end
    
    local position = index + 1
    local data = self:GetRecruitData()[position]
    if not data then return end
    
    local cell = gridView:NewListViewItem(PrefabCellName)
    local scr = CfUtils.GetLuaScr(cell, "Game.OverseaChat.OverseaChatRecruitPanelCell")
    if isNotNull(scr) then
        scr:RefreshCell(data, position, Bind(self, self.CellJoinBtnOnClickHandler))
    end
    return cell
end
--endregion handler

--region public
---刷新界面
function OverseaChatRecruitPanel:Refresh(env)
    self:RefreshUI()
end
--endregion public

--region private
---刷新ui
function OverseaChatRecruitPanel:RefreshUI()
    self:RefreshListView()
end

---刷新列表
function OverseaChatRecruitPanel:RefreshListView()
    if isNull(self.ScrollView) then return end

    ---@type Social
    local socialLine = AppService:GetInstance():GetSocialLine()
    local data = self:FilterRecruitData(clone(checkTable(socialLine.recruitData)))
    self:SetRecruitData(data)
    
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(#data, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #data)
    end
    self.ScrollView:MovePanelToItemByIndex(0, 0, 0)
end

---过滤招募数据
---@param recruitData table 
function OverseaChatRecruitPanel:FilterRecruitData(recruitData)
    local combatType = self:GetCombatType()
    local difficultyType = self:GetDifficultyType()
    local filterData = {}
    local function checkCombatType(data)
        if combatType == 0 then return true end
        
        return checkInt(data.bossTypeId) == combatType
    end
    local function checkDifficultyType(data)
        if difficultyType == 0 then return true end

        return checkInt(data.questId)%10 == difficultyType
    end
    for _, v in ipairs(recruitData) do
        if checkCombatType(v) and checkDifficultyType(v) then
            table.insert(filterData, v)
        end
    end
    return filterData
end

---清空列表
function OverseaChatRecruitPanel:ClearListView()
    if isNull(self.ScrollView) then return end
    if self.ScrollView.IsListViewInit then
        GameUtils.ReloadData(self.ScrollView, 0)
    end
end
--endregion private

--region get / set
---设置招募数据
---@param recruitData table 招募数据
function OverseaChatRecruitPanel:SetRecruitData(recruitData)
    self._recruitData = checkTable(recruitData)
end

---获取招募数据
function OverseaChatRecruitPanel:GetRecruitData()
    return self._recruitData
end

---设置战斗类型
function OverseaChatRecruitPanel:SetCombatType(combatType)
    self._combatType = checkInt(combatType)
end

---获取战斗类型
function OverseaChatRecruitPanel:GetCombatType()
    return self._combatType
end

---设置难度类型
function OverseaChatRecruitPanel:SetDifficultyType(difficultyType)
    self._difficultyType = checkInt(difficultyType)
end

---获取难度类型
function OverseaChatRecruitPanel:GetDifficultyType()
    return self._difficultyType
end

---获取难度数量
function OverseaChatRecruitPanel:GetDifficultyNum()
    local questVo = CfUtils.GetCf(AutoIds.IdSetting3027, "RegionAnnihilationQuestVo", true)
    local num = 0
    for i, v in ipairs(questVo) do
        if v.monsterType == 1 then
            num = num + 1
        end
    end
    return num
end
--endregion get / set

return OverseaChatRecruitPanel